{"file_path":"tests/test_spec.py","content":"import pytest

from safety_evals.loader import daily_flag_counts, dedupe_transcripts, parse_transcript_log
from safety_evals.metrics import (
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def test_monitor_flag_rate_none_counts_in_denominator():
    assert monitor_flag_rate([
        {"flagged": True}, {"flagged": False}, {"flagged": None}
    ]) == 1 / 3
    assert monitor_flag_rate([]) == 0.0
    assert monitor_flag_rate([{"flagged": None}]) == 0.0


def test_pooled_rate_weights_transcripts_not_groups():
    groups = {"small": [{"flagged": True}], "large": [{"flagged": False}] * 3, "empty": []}
    assert pooled_flag_rate(groups) == 0.25
    assert pooled_flag_rate({}) == 0.0
    assert pooled_flag_rate({"empty": []}) == 0.0


def test_flags_in_window():
    assert flags_in_window([1, 2, 3], 0) == 0
    assert flags_in_window([1, 2, 3], 1) == 3
    assert flags_in_window([1, 2, 3], 2) == 5
    assert flags_in_window([1, 2, 3], 4) == 6
    assert flags_in_window([], 2) == 0


def test_parse_transcript_log_flags_and_skipped_lines():
    lines = ["  # comment,ignored,here", "", "  \t ", " x , 3 , 1 ",
             " y , -2 , 0 ", " z , 0 ,  "]
    assert parse_transcript_log(lines) == [
        {"id": "x", "day": 3, "flagged": True},
        {"id": "y", "day": -2, "flagged": False},
        {"id": "z", "day": 0, "flagged": None},
    ]


@pytest.mark.parametrize("line", ["x,1", "x,1,0,extra", "x,no,1", "x,1,yes"])
def test_parse_transcript_log_errors_include_original_line_number(line):
    with pytest.raises(ValueError, match=r"line 4\b"):
        parse_transcript_log(["# comment", " ", "x,1,0", line])


def test_dedupe_keeps_last_duplicate_then_sorts_by_day_and_id():
    events = [
        {"id": "a", "day": 1, "flagged": True},
        {"id": "b", "day": 2, "flagged": True},
        {"id": "c", "day": 2, "flagged": False},
        {"id": "a", "day": 2, "flagged": None},
        {"id": "d", "day": 0, "flagged": False},
    ]
    assert dedupe_transcripts(events) == [events[4], events[3], events[1], events[2]]
    assert dedupe_transcripts([]) == []


def test_daily_flag_counts_inclusive_range_and_empty_days():
    events = [
        {"day": 0, "flagged": True}, {"day": 1, "flagged": True},
        {"day": 1, "flagged": True}, {"day": 2, "flagged": None},
        {"day": 3, "flagged": False}, {"day": 4, "flagged": True},
    ]
    assert daily_flag_counts(events, 1, 3) == [2, 0, 0]
    assert daily_flag_counts([], -1, 1) == [0, 0, 0]
    assert daily_flag_counts(events, 3, 1) == []


def test_monitor_summary_calendar_window_weighting_and_precision():
    groups = {
        "a": [{"day": 1, "flagged": True}],
        "b": [{"day": 5, "flagged": False}, {"day": 6, "flagged": None}],
        "empty": [],
    }
    assert monitor_summary(groups, 2) == {"rate": 0.333, "recent": 0, "groups": 2}
    assert monitor_summary(groups, 6) == {"rate": 0.333, "recent": 1, "groups": 2}
    assert monitor_summary(groups, 0)["recent"] == 0
    assert monitor_summary({"empty": []}, 3) == {"rate": 0.0, "recent": 0, "groups": 0}
    assert monitor_summary({}, 3) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_flagged_groups_excludes_empty_and_sorts_ties_by_name():
    groups = {"z": [{"flagged": True}], "empty": [], "a": [{"flagged": True}],
              "low": [{"flagged": None}]}
    assert top_flagged_groups(groups, 5) == ["a", "z", "low"]
    assert top_flagged_groups(groups, 1) == ["a"]
    assert top_flagged_groups(groups, 0) == []


def test_flag_rate_by_group_includes_empty_and_sorts_keys():
    result = flag_rate_by_group({"z": [], "b": [{"flagged": None}], "a": [{"flagged": True}]})
    assert result == {"a": 1.0, "b": 0.0, "z": None}
    assert list(result) == ["a", "b", "z"]


def test_longest_flag_streak_resets_on_nonpositive_values():
    assert longest_flag_streak([1, 1, 0, 3, -1, 2, 4, 5]) == 3
    assert longest_flag_streak([0, -1, 0]) == 0
    assert longest_flag_streak([]) == 0
